import math

M = 2004

# Function to calculate binomial coefficient C(n, k)
def combinations(n, k):
    if k < 0 or k > n:
        return 0
    return math.comb(n, k)

# Search for the smallest n such that C(n, k) >= M for some k <= n/2
n = 1
while True:
    found = False
    # Check k from 0 up to n // 2
    for k in range(n // 2 + 1):
        c = combinations(n, k)
        if c >= M:
            print(f"Found: n={n}, k={k}, C(n, k) = {c}")
            found = True
            break
    if found:
        break
    n += 1

# Also check the total number of subsets (k is not restricted, i.e., 2^n)
n_subset = 1
while (2**n_subset) < M:
    n_subset += 1
print(f"Smallest n for 2^n >= M: n={n_subset}")

