def find_min_n(m):
    for n in range(1, 15):
        all_vectors = list(product([0,1], repeat=n))
        if len(all_vectors) < 2*m:
            continue

        # To make it faster, we can iterate over all possible sets V of size m.
        # But that's still too many.
        # Instead, let's just use the property that there must exist 
        # a set V of size m and a set W of size m such that V and W are disjoint
        # and no vector in V is orthogonal to any vector in W.

        # Let's use a randomized approach to find V and W.
        for _ in range(100000):
            V = random.sample(all_vectors, m)
            # Calculate the set of all vectors w that are not orthogonal to any v in V.
            W_possible = []
            for w in all_vectors:
                if w not in V:
                    if all(sum(v[k] * w[k] for k in range(n)) >= 1 for v in V):
                        W_possible.append(w)

            if len(W_possible) >= m:
                return n
    return None

